def seed_workflows():
    existing = {x['id'] for x in all_docs('workflows')}
    for wf in WORKFLOWS:
        if wf['id'] not in existing:
            put('workflows', wf['id'], wf)

def get_workflows():
    seed_workflows()
    return all_docs('workflows')
